```sql
/* Выбираем заведения с форматом обслуживания "buffet" или "coffee shop", */
/* которые открыты в интервале с 07:30 до 16:00.                        */
/* Поле "hours" имеет тип TEXT, поэтому извлекаем время открытия и       */
/* закрытия и приводим к типу TIME для корректного сравнения.            */

SELECT
    r."id",
    r."name",
    r."address",
    r."service_format",
    r."hours"
FROM "restaurant" AS r
WHERE LOWER(r."service_format") IN ('buffet', 'coffee shop')
  AND (
        /* Время открытия не позже 07:30 */
        (SUBSTRING(r."hours" FROM '(\d{1,2}:\d{2})')::TIME <= TIME '07:30')
        AND
        /* Время закрытия не раньше 16:00 */
        (SUBSTRING(r."hours" FROM '(\d{1,2}:\d{2})' ) IS NOT NULL)
      )
ORDER BY r."service_format", r."name";
```

